def badge(kind,text): return f'<span class="badge {kind}">{text}</span>'
def section(i,title,body): return f'<section id="{i}"><h2>{title}</h2>{body}</section>'
def cards(items): return '<div class="cards">'+''.join(f'<article class="card"><h3>{a}</h3><p>{b}</p></article>' for a,b in items)+'</div>'
def table(headers,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def code(s): return f'<pre><button class="copy" type="button">Copy</button><code>{escape(s)}</code></pre>'
def callout(title,text,kind=''): return f'<aside class="callout {kind}"><strong>{title}</strong><p>{text}</p></aside>'
def flow(nodes): return '<div class="product-map">'+''.join(f'<div class="map-node">{x}</div>'+('<span>→</span>' if i<len(nodes)-1 else '') for i,x in enumerate(nodes))+'</div>'
