add('', 'Protect the conditions behind your position.','Getting started','Kelvara continuously verifies the controls behind your DeFi positions and helps you respond while there is still time to act.',
 cards([('Position-specific','Know exactly which capital a change affects.'),('Evidence-backed','Security conclusions are backed by current onchain evidence.'),('Self-custodial','Your wallet remains the authority.')])+section('map','How Kelvara fits together',flow(['Position','Governance','Safeguards','Incident','Protection / ExitRail'])+'<p>Start with the capital. Trace what controls it, verify expected conditions, understand change, then use an owner-authorized response.</p>')+section('start','Start with a position','<p>Kelvara connects each supported position to its control plane, expected safeguards, current evidence, severity, and available response. Findings stay scoped to the affected position.</p>'+badge('live','Live Mainnet workspace')+badge('beta','Coverage constrained')),[('map','How Kelvara fits together'),('start','Start with a position')])
