add('positions','Positions','Product','The exact capital-bearing object that Kelvara evaluates.',section('identity','Stable identity','<p>Position records bind network, protocol, resource type, vault address, wallet exposure, asset, and capability state. A stable target ID prevents evidence from one vault leaking into another.</p>'+code('solana:{network}:{protocol}:{resourceType}:{address}'))+section('isolation','Position isolation',callout('One position, one conclusion.','A problem in position A never makes position B appear unhealthy.')),[('identity','Stable identity'),('isolation','Position isolation')])
add('governance','Governance','Product','See who controls a position, what authority they hold, and what actions are moving.',section('control','Control Map',cards([('Controller','Provider, multisig, vault identity.'),('Membership','Members, roles, permissions, threshold.'),('Activity','Current proposals and finalized changes.')])+badge('beta','Authenticated Mainnet')+badge('live','Squads V4 adapter'))+section('lifecycle','Governance lifecycle','<p>Actions can expose proposal, approvals, rejection, threshold, timelock, execution, cancellation, source signature, finalized slot, decoded instructions, and provenance. Unknown instructions remain unknown.</p>'),[('control','Control Map'),('lifecycle','Governance lifecycle')])
add('safeguards','Safeguards','Product','Position-scoped rules that compare expected conditions with current evidence.',section('scope','Scope hierarchy',flow(['Wallet','Position','Group','Rule','Evidence']))+section('groups','Safeguard groups',cards([('Governance','Admin and governance controls.'),('Program','Upgrade and executable assumptions.'),('Access','Withdrawal and vault access.'),('Asset','Oracle and asset integrity.'),('Economic','Configuration and economic limits.'),('Evidence','Freshness and source integrity.')]))+section('history','History boundary','<p>Current UI supports scoped results and explicit unknown or incomplete states. Append-only safeguard transitions, daily worst state, and 90-day history remain planned.</p>'+badge('beta','Position safeguards')+badge('planned','Transition history')+badge('planned','90-day history')),[('scope','Scope hierarchy'),('groups','Safeguard groups'),('history','History boundary')])
add('protection','Protection','Product','Owner-controlled response preparation for supported positions.',section('modes','Response modes',cards([('Immediate evacuation','Review and approve an exact withdrawal now.'),('ExitRail','Authorize an exact response in advance.'),('Local execution','Owner-operated execution contract; planned publicly.')]))+section('boundary','Production boundary',callout('Live on Mainnet.','All three supported Kamino vaults offer immediate evacuation, protection enrollment, and automatic execution. When a bound safeguard fails for its minimum breach duration on fresh evidence, Kelvara submits your pre-signed durable-nonce variants cheapest first and stops at the first confirmed success. A kill switch, a time-limited grant, and fail-closed checks gate every automatic send.')+badge('live','Automatic Mainnet execution')),[('modes','Response modes'),('boundary','Production boundary')])
add('exitrail','Kelvara ExitRail','Product','Sign once. Keep your exact exit ready.',section('authorization','Durable authorization','<p>An ExitRail authorization is three wallet-signed priority-fee variants of the same exit. Each fixes destination, accounts, instructions, amounts, signer set, and fee policy inside wallet-signed transaction bytes. Any mutation invalidates the signature. Durable nonces keep the exact authorization usable beyond a recent-blockhash window.</p>'+badge('live','Mainnet enrollment')+badge('live','Durable nonces')+badge('live','Automatic Mainnet execution'))+section('control','Owner control','<p>Kelvara may submit only an exact transaction already authorized by the owner and only when applicable policy and evidence checks permit it. Unused authorization can be invalidated by advancing or reclaiming nonce accounts.</p><details><summary>Technical detail: transaction variants</summary><p>An integration may prepare bounded priority-fee variants. Each remains a separately signed exact transaction, not an open mandate.</p></details>'),[('authorization','Durable authorization'),('control','Owner control')])
add('wallet-exposure','Wallet exposure','Product','Who can move your tokens? Kelvara finds active spending permissions and verifies the policy behind each one.',section('scan','What Kelvara checks',cards([('Token delegates','Every SPL Token and Token-2022 account the wallet owns, read at finalized commitment.'),('Allowance in reach','The delegated amount, capped by the current balance it can actually move.'),('Recent activity','Programs seen in the latest 20 finalized transactions.')])+badge('live','Mainnet'))+section('verification','Automatic delegation verification','<p>For each delegate found, Kelvara looks for the policy that governs it in the Subscriptions Delegation Program. A policy counts as verified only when its owner, delegate, and mint match the token account and its address re-derives from the transaction that created it. Verified policies show their spending cap, remaining amount, expiry, and the slot they were verified at.</p>'+callout('Unverified is not safe.','A delegate without a verified policy is shown with an unknown cap, never as limited.'))+section('revoke','Revoke in one approval','<p>Revoking clears the token delegate and closes its policy and authority accounts in one wallet-signed transaction, returning their rent. Kelvara re-reads the accounts before signing and again after finality, and reports success only when the delegate is gone on-chain.</p>')+section('limits','Scope','<ul><li>Covers token-account delegates only.</li><li>Recent activity is the latest 20 finalized signatures, not lifetime history.</li><li>A program in recent activity is not proof of current permission or risk.</li><li>Wallet connections, stolen keys, protocol-specific authorities, and Token-2022 extensions are not fully analyzed.</li></ul>'),[('scan','What Kelvara checks'),('verification','Automatic delegation verification'),('revoke','Revoke in one approval'),('limits','Scope')])
add('evidence','Evidence','Trust','The proof behind every important security conclusion.',section('claims','Evidence-backed claims',cards([('Subject','Network, position, vault, multisig.'),('Observation','Finalized slot and observation time.'),('Provenance','Source, hashes, decoder and version.')]))+section('freshness','Current and last verified','<p><strong>Current</strong> answers what Kelvara can verify now. <strong>Last verified</strong> records the most recent successful observation. Earlier good evidence cannot remain a current green state after verification disappears.</p>'),[('claims','Evidence-backed claims'),('freshness','Current and last verified')])
add('monitoring-health','Monitoring health','Trust','Kelvara reports whether it can still observe—not only what it last observed.',section('states','Health states',table(['State','Meaning'],[['Healthy','Current evidence exists within freshness policy.'],['Stale','Evidence is too old for a current-safe conclusion.'],['Unavailable','The observation path failed or returned unusable evidence.'],['Not monitored','No active observation capability is configured.']]))+section('failure','Fail closed',callout('No silent green.','Missing, malformed, stale, unavailable, or mismatched evidence is never converted into safe.')),[('states','Health states'),('failure','Fail closed')])
add('self-custody','Self-custody','Trust','Your wallet remains the authority across inspection, enrollment, and response.',section('authority','What Kelvara cannot do','<ul><li>Kelvara never receives a seed phrase or private key.</li><li>Wallet authentication grants no arbitrary transaction rights.</li><li>Read-only inspection remains separate from transaction approval.</li><li>Protection uses bounded, owner-signed transaction bytes.</li></ul>'),[('authority','What Kelvara cannot do')])
add('security','Security model','Trust','Bounded authority, independent validation, encrypted storage, and fail-closed evidence.',section('principles','Security principles',cards([('Bounded authorization','Exact position, destination, instructions, signer set, and fee policy.'),('Independent validation','Decode, simulate, and check before and after signing.'),('Fail closed','Unknown evidence or transaction mismatch blocks trust.')]))+section('upgrades','Program upgrades','<p>A stable program address does not imply stable code. Code change requires quarantine and renewed validation before earlier authorization can remain trusted.</p><details><summary>Storage detail</summary><p>Signed authorization is encrypted at rest where protection enrollment applies. Encryption protects storage; exact-byte validation protects authorization semantics.</p></details>'),[('principles','Security principles'),('upgrades','Program upgrades')])
add('limitations','Limitations','Trust','What Kelvara does not promise.',section('limits','Known limits','<ul><li>Kelvara cannot predict every exploit or protocol failure.</li><li>Monitoring cannot guarantee enough time or liquidity to exit.</li><li>Control continuity alone does not prove code or economics safe.</li><li>Execution depends on the protocol and Solana accepting the transaction.</li><li>Coverage differs by position and remains explicit.</li><li>Kelvara is not insurance, an audit, investment advice, or a guarantee against loss.</li></ul>'),[('limits','Known limits')])
