add('developers/local-execution','Local execution','Developers','An owner-operated execution boundary for exact, pre-authorized responses.',section('contract','Execution contract','<p>Kelvara supplies incident identity, exact subject, policy identity, evidence reference, and prepared-response context. Owner infrastructure decides whether to submit.</p>')+section('safety','Required safety controls','<ul><li>Verify immutable transaction identity.</li><li>Simulate immediately before submission.</li><li>Atomically claim one execution attempt.</li><li>Persist the known signature before waiting.</li><li>Reconcile uncertain submission; never blindly retry.</li></ul>'+badge('planned','Public local executor')),[('contract','Execution contract'),('safety','Required safety controls')])
add('developers/contracts','Contracts & schemas','Developers','Canonical IDs and fail-closed records for positions, governance, safeguards, and evidence.',section('position','Position ID',code('solana:{network}:{protocol}:{resourceType}:{address}'))+section('records','Core records',cards([('Governance','Provider identity, membership, active actions, finalized history, freshness.'),('Safeguard','Target ID, binding ID, rule/version, result, reason, evidence reference.'),('Evidence','Source, subject, observation identity, hashes, decoder provenance, freshness.')]))+section('errors','Error semantics','<p>Wrong network, unknown subject, stale evidence, unresolved instruction, failed simulation, uncertain send, or immutable mismatch remain explicit machine states.</p>'),[('position','Position ID'),('records','Core records'),('errors','Error semantics')])
